const CHILD_NAMES=['Ada','Beni','Cass','Dara','Eli','Fen','Gia','Hal','Ines','Jo','Kit','Lior','Mimi','Noor','Ori','Pip','Quinn','Remy','Sam','Tove','Uma','Vic','Wren','Yara','Zed'];
const TEMPERAMENTS=['curious','shy','bold','sensitive','steady'];
const KID_INTERESTS=['drawing','music','science','sport','reading','cooking','building','animals','games','nature'];
const STAGES={infant:[0,'Little one'],child:[3,'Child'],teen:[10,'Teenager'],adult:[17,'Young adult']};
function freshPeople(){return {v:1,roster:{},order:[],partner:null,status:'single',household:[],exes:[],plans:[],memories:[],routines:[],lastMeet:-9,seq:0,season:0,archive:[],flags:{}};}
function freshRel(){return {affection:5,trust:5,tension:0,tier:'acquaintance',kept:0,broken:0,gifts:[],lastContact:0,repairSince:-1,apologies:0,history:[],met:0,fatigue:{},counsel:0,leaving:false,leavingSince:-1,reduced:-1,lastNeglect:-9};}
function makeAdult(c,day){return {id:c.id,kind:'adult',name:c.name,age:c.age,gender:c.gender,stage:'adult',job:c.job,path:c.path,income:c.income,traits:c.traits.slice(),interests:c.interests.slice(),values:c.values.slice(),dateable:!!c.dateable,family:c.family||'',avail:c.avail.slice(),seed:c.seed.slice(),goalIndex:0,goalProgress:0,milestone:false,savings:Math.round(c.income*DAY*20),rel:freshRel(),ties:Object.assign({},c.ties),joined:day,parents:[],children:[],home:false};}
function normalizePeople(raw,d){
 const p=freshPeople();const day=d.house?.day||0;
 // roster: curated adults (met or not) + children / adult children stored in the save
 for(const c of CAST){const r=raw?.roster?.[c.id];const a=makeAdult(c,day);if(r&&typeof r==='object'){a.met=r.rel?.met!==undefined&&r.rel.met!==false;normRel(a.rel,r.rel);a.goalIndex=Math.floor(num(r.goalIndex,50));a.goalProgress=clamp(num(r.goalProgress),0,3);a.milestone=r.milestone===true;a.savings=num(r.savings,1e12);a.home=r.home===true;a.children=Array.isArray(r.children)?r.children.filter(x=>typeof x==='string').slice(0,8):[];a.joined=num(r.joined);a.income=num(r.income,1e6)||c.income;a.job=typeof r.job==='string'?r.job.slice(0,60):c.job;}p.roster[c.id]=a;}
 if(raw?.roster)for(const [id,r] of Object.entries(raw.roster)){if(p.roster[id]||typeof id!=='string'||!/^k\d+$/.test(id)||!r||typeof r!=='object')continue;const k={id,kind:'child',name:String(r.name||'Kid').slice(0,30),gender:['f','m','n'].includes(r.gender)?r.gender:'n',stage:STAGES[r.stage]?r.stage:'infant',born:Math.floor(num(r.born,1e6)),temperament:TEMPERAMENTS.includes(r.temperament)?r.temperament:'steady',interests:(Array.isArray(r.interests)?r.interests.filter(x=>KID_INTERESTS.includes(x)):[]).slice(0,3),confidence:clamp(num(r.confidence,100)||50,0,100),wellbeing:clamp(num(r.wellbeing,100)||70,0,100),independence:clamp(num(r.independence),0,100),expectations:['gentle','balanced','high'].includes(r.expectations)?r.expectations:'balanced',school:['public','private','home'].includes(r.school)?r.school:'public',seed:Array.isArray(r.seed)&&r.seed.length===6?r.seed.map(n=>Math.floor(num(n,9))):[2,0,0,0,3,0],adopted:r.adopted===true,parents:Array.isArray(r.parents)?r.parents.filter(x=>typeof x==='string').slice(0,2):[],outcome:typeof r.outcome==='string'?r.outcome.slice(0,40):'',home:r.home!==false,rel:freshRel(),job:typeof r.job==='string'?r.job.slice(0,60):'',income:num(r.income,1e6),path:PATHS.some(x=>x.id===r.path)?r.path:'',traits:[],values:[],avail:[0,1,2,3,4,5,6],ties:{},goalIndex:0,goalProgress:0,milestone:false,savings:0,dateable:false,joined:num(r.joined),age:0,children:[],interestsShown:Math.floor(num(r.interestsShown,3)),met:true};if(!k.interests.length)k.interests=[KID_INTERESTS[k.born%KID_INTERESTS.length]];normRel(k.rel,r.rel);k.rel.met=true;p.roster[id]=k;}
 p.order=(Array.isArray(raw?.order)?raw.order:[]).filter(id=>p.roster[id]&&p.roster[id].rel.met).slice(0,60);
 for(const id of Object.keys(p.roster))if(p.roster[id].rel.met&&!p.order.includes(id))p.order.push(id);
 p.status=['single','dating','together','married','separated'].includes(raw?.status)?raw.status:'single';
 p.partner=typeof raw?.partner==='string'&&p.roster[raw.partner]&&p.roster[raw.partner].kind==='adult'&&p.roster[raw.partner].rel.met?raw.partner:null;if(!p.partner&&p.status!=='single'&&p.status!=='separated')p.status='single';
 if(p.partner)p.roster[p.partner].rel.tier=p.status==='married'?'spouse':p.status==='together'?'partner':'dating';
 p.exes=(Array.isArray(raw?.exes)?raw.exes:[]).filter(id=>p.roster[id]).slice(0,10);
 p.household=(Array.isArray(raw?.household)?raw.household:[]).filter((id,i,a)=>p.roster[id]&&a.indexOf(id)===i&&id!==p.partner).slice(0,10);if(p.partner&&(p.status==='together'||p.status==='married'))p.household.unshift(p.partner);
 for(const id of p.household)p.roster[id].home=true;
 p.plans=(Array.isArray(raw?.plans)?raw.plans:[]).filter(c=>c&&typeof c==='object'&&p.roster[c.person]&&ACTIVITIES[c.activity]&&['plan','promise','duty'].includes(c.type)).map(c=>({id:String(c.id||'c'+(++p.seq)).slice(0,24),day:Math.floor(num(c.day,1e9)),person:c.person,activity:c.activity,type:c.type,label:String(c.label||ACTIVITIES[c.activity].name).slice(0,80),recurring:Number.isInteger(c.recurring)&&c.recurring>=0&&c.recurring<7?c.recurring:null,moved:Math.floor(num(c.moved,9))})).slice(0,12);
 p.routines=(Array.isArray(raw?.routines)?raw.routines:[]).filter(r=>r&&p.roster[r.person]&&ACTIVITIES[r.activity]&&Number.isInteger(r.weekday)).map(r=>({person:r.person,activity:r.activity,weekday:clamp(r.weekday,0,6)})).slice(0,6);
 p.memories=(Array.isArray(raw?.memories)?raw.memories:[]).filter(m=>m&&typeof m==='object'&&typeof m.title==='string').map(m=>({day:Math.floor(num(m.day,1e9)),season:Math.floor(num(m.season,1e6)),type:String(m.type||'moment').slice(0,24),title:m.title.slice(0,80),text:String(m.text||'').slice(0,300),people:(Array.isArray(m.people)?m.people:[]).filter(x=>typeof x==='string').slice(0,6),home:typeof m.home==='string'?m.home.slice(0,20):'',gen:Math.floor(num(m.gen,1e6))||1})).slice(-120);
 p.lastMeet=num(raw?.lastMeet)||-9;p.seq=Math.max(Math.floor(num(raw?.seq,1e9)),p.seq);p.season=Math.floor(num(raw?.season,1e9));
 p.archive=(Array.isArray(raw?.archive)?raw.archive:[]).filter(a=>a&&typeof a==='object').slice(-10).map(a=>({generation:Math.floor(num(a.generation,1e6)),summary:String(a.summary||'').slice(0,2000),memories:(Array.isArray(a.memories)?a.memories:[]).slice(-60).map(m=>({title:String(m.title||'').slice(0,80),text:String(m.text||'').slice(0,300),season:Math.floor(num(m.season,1e6))})),people:(Array.isArray(a.people)?a.people:[]).slice(0,30).map(x=>String(x).slice(0,80))}));
 if(raw?.flags&&typeof raw.flags==='object')for(const [k,v] of Object.entries(raw.flags))if(typeof k==='string'&&k.length<32&&(typeof v==='number'||typeof v==='boolean'))p.flags[k]=v;
 d.people=p;return p;
}
function normRel(rel,r){if(!r||typeof r!=='object')return;rel.affection=clamp(num(r.affection),0,100);rel.trust=clamp(num(r.trust),0,100);rel.tension=clamp(num(r.tension),0,100);rel.tier=['acquaintance','friend','close','dating','partner','spouse','ex','family'].includes(r.tier)?r.tier:'acquaintance';rel.kept=Math.floor(num(r.kept,1e6));rel.broken=Math.floor(num(r.broken,1e6));rel.gifts=(Array.isArray(r.gifts)?r.gifts:[]).filter(Number.isFinite).slice(-8);rel.lastContact=num(r.lastContact);rel.repairSince=Number.isFinite(r.repairSince)?r.repairSince:-1;rel.apologies=Math.floor(num(r.apologies,100));rel.history=(Array.isArray(r.history)?r.history:[]).filter(h=>h&&typeof h.text==='string').map(h=>({day:Math.floor(num(h.day,1e9)),text:h.text.slice(0,160)})).slice(-14);rel.met=r.met===true||r.met===undefined&&rel.affection>5;rel.counsel=Math.floor(num(r.counsel,10));rel.leaving=r.leaving===true;rel.leavingSince=Number.isFinite(r.leavingSince)?r.leavingSince:-1;rel.reduced=Number.isFinite(r.reduced)?r.reduced:-1;rel.lastNeglect=num(r.lastNeglect)||-9;if(r.fatigue&&typeof r.fatigue==='object')for(const [k,v] of Object.entries(r.fatigue))if(ACTIVITIES[k]&&Number.isFinite(v))rel.fatigue[k]=v;}
// ---------- lookups
const PP=(s=S)=>{const p=s.people||(s.people=freshPeople());if(!p.roster[CAST[0].id])for(const c of CAST)if(!p.roster[c.id])p.roster[c.id]=makeAdult(c,s.house?.day||0);return p;};
const person=(id,s=S)=>PP(s).roster[id]||null;
const partnerOf=(s=S)=>PP(s).partner?person(PP(s).partner,s):null;
const livingTogether=(s=S)=>!!PP(s).partner&&['together','married'].includes(PP(s).status);
const kidsAtHome=(s=S)=>PP(s).household.map(id=>person(id,s)).filter(k=>k&&k.kind==='child'&&k.home);
const allKids=(s=S)=>Object.values(PP(s).roster).filter(k=>k.kind==='child');
const metPeople=(s=S)=>PP(s).order.map(id=>person(id,s)).filter(Boolean);
const season=(s=S)=>Math.floor(H(s).day/SEASON);
const weekday=(s=S)=>H(s).day%7;
const freeToday=(p,s=S)=>p.kind==='child'||p.home||p.avail.includes(weekday(s));
const nextFreeDay=(p,from,s=S)=>{for(let d=from;d<from+8;d++)if(p.kind==='child'||p.home||p.avail.includes(d%7))return d;return from+1;};
const playerInterests=(s=S)=>Object.entries(s.hobbies).filter(([,l])=>l>0).map(([h])=>HOBBY_INTEREST[h]).filter(Boolean);
const shared=(p,s=S)=>p.interests.filter(i=>playerInterests(s).includes(i));
function tierOf(p){const r=p.rel;if(['dating','partner','spouse','ex','family'].includes(r.tier))return r.tier;if(r.reduced>=0&&r.reduced+SEASON>H().day)return 'acquaintance';if(r.affection>=60&&r.trust>=55&&r.tension<40)return 'close';if(r.affection>=25&&r.trust>=20)return 'friend';return 'acquaintance';}
const TIER_LABEL={acquaintance:'Acquaintance',friend:'Friend',close:'Close friend',dating:'Dating',partner:'Living together',spouse:'Married',ex:'Former partner',family:'Family'};
function feelText(p){const r=p.rel;if(r.leaving)return 'is thinking seriously about leaving';if(r.tension>=70)return 'is hurt and keeping distance';if(r.tension>=40)return 'has things left unsaid';if(r.reduced>=0&&r.reduced+SEASON>H().day)return 'is taking some space from you';if(r.affection>=80&&r.trust>=70)return 'feels at home with you';if(r.affection>=60)return 'is glad you\'re around';if(r.affection>=30)return 'enjoys your company';if(r.affection>=15)return 'is getting to know you';return 'barely knows you yet';}
function addHistory(p,text){p.rel.history.push({day:H().day,text:text.slice(0,160)});if(p.rel.history.length>14)p.rel.history.shift();}
function bump(p,{aff=0,trust=0,tension=0}={}){const r=p.rel;r.affection=clamp(r.affection+aff,0,100);r.trust=clamp(r.trust+trust,0,100);r.tension=clamp(r.tension+tension,0,100);if(tension<0&&r.tension<20&&r.repairSince>=0){r.repairSince=-1;}}
function memory(type,title,text,people=[]){const p=PP();p.memories.push({day:H().day,season:season(),type,title,text,people,home:activeHome().id,gen:S.generation});if(p.memories.length>120)p.memories.shift();note(`📖 ${title}`);}
// ---------- meeting people
const MEET_CONTEXT={mara:s=>s.path==='medicine'||s.hobbies.fitness>0,theo:s=>s.path==='tech'||s.hobbies.music>0,priya:s=>s.path==='culinary'||s.hobbies.garden>0,dev:s=>s.path==='trades'||Object.keys(s.business).length>0,june:s=>s.path==='finance'||portfolioValue(s)>1000,sol:s=>s.path==='creative'||s.hobbies.music>0,nadia:s=>s.hobbies.garden>0||activeHome(s).id!=='room',kai:s=>s.path==='culinary'||s.hobbies.music>0,ravi:s=>Object.keys(s.business).length>0||s.clicks>200,elena:s=>activeHome(s).id!=='room'||s.hobbies.garden>0};
function meetCandidate(){const p=PP(),unmet=CAST.filter(c=>!p.roster[c.id].rel.met);if(!unmet.length)return null;const fits=unmet.filter(c=>MEET_CONTEXT[c.id](S));const pool=fits.length?fits:unmet;return pool[Math.floor(Math.random()*pool.length)];}
function meetPerson(id){const p=PP(),q=person(id);if(!q||q.rel.met)return false;q.rel.met=true;q.rel.affection=8;q.rel.trust=8;q.rel.lastContact=H().day;q.joined=H().day;p.order.push(id);p.lastMeet=H().day;addHistory(q,'You met.');memory('meet',`Met ${q.name}`,`${q.name}, ${q.job.toLowerCase()}. ${CAST.find(c=>c.id===id)?.line||''}`,[id]);return true;}
// ---------- interactions
const ACTIVITIES={
 talk:{name:'Catch up',cost:()=>0,inPerson:false,desc:'A real conversation. Free.',apply:(p,r)=>{const f=r.fatigue.talk===H().day;bump(p,{aff:f?1:3,trust:f?0:1});return f?`${p.name}: "We talked already today. Still nice."`:talkLine(p);}},
 coffee:{name:'Coffee or a meal',cost:()=>Math.ceil(Math.max(12,clickPay()*2)),inPerson:true,desc:'An hour together, on you.',apply:(p,r)=>{const f=r.fatigue.coffee===H().day;bump(p,{aff:f?1:5,trust:f?0:1,tension:-1});return f?'Another round. Diminishing charm.':`${p.name} tells you about ${goalOf(p).text.toLowerCase()}.`;}},
 outing:{name:'Hobby outing',cost:()=>Math.ceil(Math.max(30,clickPay()*4)),inPerson:true,desc:'Do something you both care about.',apply:(p,r)=>{const sh=shared(p).length>0;bump(p,{aff:sh?8:4,trust:sh?3:1,tension:-2});return sh?`Shared interest in ${INTERESTS[shared(p)[0]].toLowerCase()}. ${p.name} lights up.`:`${p.name} came along, but it\'s more your thing than theirs.`;}},
 help:{name:'Offer practical help',cost:p=>goalOf(p).need==='money'?Math.ceil(Math.max(150,clickPay()*20)):0,inPerson:true,desc:'Money, a day of your time, or a push toward their goal.',apply:(p,r)=>{const g=goalOf(p);if(g.need==='time')H().fx.restUntil=Math.max(H().fx.restUntil,H().day+1);bump(p,{aff:3,trust:8,tension:-3});p.goalProgress=Math.min(3,p.goalProgress+1);if(p.goalProgress>=3){p.milestone=true;return `${p.name} is close: ${g.text.toLowerCase()} is nearly done. There\'ll be something to celebrate.`;}return `You helped ${p.name} with ${g.text.toLowerCase()} (${g.need}). Trust grows.`;}},
 celebrate:{name:'Celebrate their milestone',cost:()=>Math.ceil(Math.max(20,clickPay()*3)),inPerson:true,desc:'Show up for something that matters to them.',apply:(p,r)=>{if(!p.milestone)return 'Nothing to celebrate right now.';const g=goalOf(p);p.milestone=false;p.goalIndex++;p.goalProgress=0;bump(p,{aff:9,trust:5,tension:-4});memory('milestone',`${p.name}: ${g.text}`,`You were there when ${p.name} got there: ${g.text.toLowerCase()}.`,[p.id]);return `${p.name} won\'t forget you were there.`;}},
 gift:{name:'Bring a gift',cost:()=>Math.ceil(Math.max(25,clickPay()*3)),inPerson:false,desc:'A small expression of care. Not a fix.',apply:(p,r)=>{r.gifts=r.gifts.filter(d=>d>H().day-15);const n=r.gifts.length;r.gifts.push(H().day);if(r.tension>=50)return `${p.name} thanks you, quietly. "It\'s kind. It doesn\'t fix things."`;bump(p,{aff:n===0?3:n===1?1:0});return n>=2?`${p.name}: "You don\'t have to keep buying things."`:`${p.name} appreciates the thought.`;}},
 apologize:{name:'Apologise',cost:()=>0,inPerson:true,desc:'Own it. Then show it.',apply:(p,r)=>{if(r.tension<5)return `${p.name}: "There\'s nothing to apologise for."`;if(r.repairSince>=0&&r.apologies>=2)return `${p.name}: "You\'ve said sorry. Show me."`;r.apologies++;if(r.repairSince<0){r.repairSince=H().day;bump(p,{tension:-5});return `${p.name} listens. The next promise you keep will count double.`;}return `${p.name} nods. Keep the next plan.`;}},
 listen:{name:'Listen to what\'s wrong',cost:()=>0,inPerson:true,desc:'Ask, and don\'t defend.',apply:(p,r)=>{if(r.tension<10)return `${p.name}: "Honestly? Things are fine."`;bump(p,{tension:-3,trust:1});return concernText(p);}},
};
function goalOf(p){const c=CAST.find(x=>x.id===p.id);if(!c)return {text:'find their footing',need:'encouragement'};return c.goals[p.goalIndex%c.goals.length];}
function talkLine(p){const r=p.rel,c=CAST.find(x=>x.id===p.id);const lines=[];if(c)lines.push(c.line);if(p.kind==='adult')lines.push(`${p.name} is working on ${goalOf(p).text.toLowerCase()}.`);if(p.kind==='child')lines.push(`${p.name} talks non-stop about ${KID_INTERESTS.includes(p.interests[0])?p.interests[0]:'school'}.`);if(r.tension>=40)lines.push(`Something is off. ${p.name} keeps it short.`);const ties=Object.entries(p.ties||{});if(ties.length&&Math.random()<.4){const [id,how]=ties[Math.floor(Math.random()*ties.length)];const q=person(id);if(q&&q.rel.met)lines.push(`${p.name} mentions ${q.name.split(' ')[0]} (${how}).`);}return lines[Math.floor(Math.random()*lines.length)];}
function concernText(p){const r=p.rel,c=[];if(r.broken>r.kept&&r.broken>0)c.push(`"You keep saying you\'ll be there and then you aren\'t."`);if(r.lastNeglect>H().day-20)c.push(`"I feel like I\'m fitting into the gaps of your work."`);if(H().arrears>0&&p.home)c.push(`"The bills are scaring me. Can we make a plan?"`);if(H().stress>=75&&p.home)c.push(`"You\'re bringing the whole day home with you."`);if(!c.length)c.push(`"I just want to know we\'re okay."`);return `${p.name}: ${c[0]}`;}
function interact(id,act){const p=person(id),a=ACTIVITIES[act];if(!p||!a||!p.rel.met||paused)return false;const r=p.rel;
 if(r.reduced>=0&&r.reduced+SEASON>H().day&&act!=='apologize'&&act!=='listen'){toast(`${p.name} is taking some space right now.`);return false;}
 if(a.inPerson&&typeof imprisoned==='function'&&imprisoned()){toast('Only letters and visits from inside.');return false;}
 if(a.inPerson&&!freeToday(p)){toast(`${p.name} isn\'t free today (free ${p.avail.map(d=>WEEKDAYS[d]).join(', ')}). Plan it instead.`);return false;}
 const cost=a.cost(p);if(cost&&!spend(cost)){toast('Not enough cash.');return false;}
 const text=a.apply(p,r);r.fatigue[act]=H().day;r.lastContact=H().day;addHistory(p,`${a.name}: ${text.replace(/^[^:]*:\s*/,'').slice(0,90)}`);note(text);checkTier(p);return true;}
function checkTier(p){const before=p.rel.tier,t=tierOf(p);if(['acquaintance','friend','close'].includes(before)&&t!==before){p.rel.tier=t;if(t==='friend')memory('friend',`Friends with ${p.name}`,`${p.name} started counting you as a friend.`,[p.id]);if(t==='close')memory('close',`${p.name}, close friend`,`Somewhere along the way ${p.name} became one of your people.`,[p.id]);}}
// ---------- romance and household decisions (partners can decline)
function compat(p){const sh=shared(p).length;const v=p.values;let c=0;if(sh)c+=1;if(v.includes('family')&&kidsAtHome().length)c+=1;if(v.includes('reliability')||v.includes('keeping your word'))c+=p.rel.kept>=p.rel.broken?1:-1;if(v.includes('planning')&&runwayDays()<7)c-=1;if(v.includes('honesty')&&p.rel.broken>2)c-=1;return c;}
function askOut(id){const p=person(id),pp=PP();if(!p||!p.dateable||pp.partner||!p.rel.met||paused)return false;const r=p.rel;
 if(r.affection<45||r.trust<35||r.tension>=30){note(`${p.name}: "I like you. I\'m not there yet." (affection, trust and calm all matter)`);return true;}
 if(compat(p)<0&&Math.random()<.5){note(`${p.name}: "I don\'t think we want the same things right now." Ask again another season.`);bump(p,{tension:2});r.fatigue.ask=H().day;return true;}
 pp.partner=id;pp.status='dating';r.tier='dating';bump(p,{aff:6});addHistory(p,'You started dating.');memory('dating',`Dating ${p.name}`,`${p.name} said yes. ${CAST.find(c=>c.id===id)?.line||''}`,[id]);return true;}
function discuss(topic){const p=partnerOf(),pp=PP(),h=H();if(!p||paused)return false;const r=p.rel,l=syncLife(S),home=activeHome();
 const declineTime=()=>{r.fatigue[topic]=h.day;bump(p,{tension:1});};
 if(r.fatigue[topic]>h.day-10){note(`${p.name}: "We talked about this a few days ago. Give it a little time."`);return true;}
 if(topic==='movein'){if(pp.status!=='dating')return false;if(home.rooms<2&&r.affection<80){note(`${p.name}: "Your place is one room. Let\'s find somewhere with space for both of us first."`);declineTime();return true;}
  if(r.trust<60||r.affection<65||r.tension>=30){note(`${p.name}: "I want to. I need a bit more time to feel sure." (trust and calm matter more than gifts)`);declineTime();return true;}
  if(p.values.includes('independence')&&r.trust<75){note(`${p.name}: "I like my own space. Ask me again when I trust this a little more."`);declineTime();return true;}
  pp.status='together';r.tier='partner';p.home=true;pp.household=[p.id,...pp.household.filter(x=>x!==p.id)];bump(p,{aff:8,trust:4});addHistory(p,'Moved in together.');memory('movein',`${p.name} moved in`,`${p.name} moved into ${home.name.toLowerCase()}. They contribute ${money(partnerContribution()*DAY)}/day toward the household and keep their own savings.`,[p.id]);return true;}
 if(topic==='marry'){if(pp.status!=='together')return false;if(r.trust<75||r.affection<75||r.tension>=25||r.broken>r.kept){note(`${p.name}: "Not yet. Not because I don\'t love you — because I want to be sure we keep our promises to each other."`);declineTime();return true;}
  if(p.values.includes('freedom')&&Math.random()<.5){note(`${p.name}: "I don\'t need a certificate to be yours. Can we stay as we are for now?"`);declineTime();return true;}
  const cost=Math.ceil(Math.max(200,clickPay()*60));if(!spend(cost)){note(`A small wedding costs about ${money(cost)}. Not enough cash right now.`);return true;}
  pp.status='married';r.tier='spouse';bump(p,{aff:10,trust:6,tension:-5});addHistory(p,'You got married.');memory('wedding',`Married ${p.name}`,`A small wedding, ${money(cost)}, and everyone who mattered in the room.`,[p.id,...kidsAtHome().map(k=>k.id)]);return true;}
 if(topic==='parent'){if(!livingTogether())return false;if(home.rooms<2){note(`${p.name}: "Not in one room. Let\'s have a door to close first."`);declineTime();return true;}
  if(r.trust<70||r.tension>=25||runwayDays()<10){note(`${p.name}: "I want us to be steady first — money, time, us."`);declineTime();return true;}
  if(!p.values.includes('family')&&Math.random()<.4){note(`${p.name}: "I\'m not sure I want to be a parent. Can we keep talking about it?"`);declineTime();return true;}
  addChild(false);return true;}
 if(topic==='balance'){bump(p,{tension:-6,trust:2});r.lastNeglect=-9;PP().flags.balanceDay=h.day;note(`${p.name}: "Thank you for asking. Two evenings a week that are ours. Deal?" A weekly dinner routine was added to your planner.`);addRoutine(p.id,'coffee',nextFreeDay(p,h.day+1)%7);return true;}
 if(topic==='money'){bump(p,{trust:3,tension:-3});note(`${p.name} contributes ${money(partnerContribution()*DAY)}/day (${Math.round(partnerShare()*100)}% of household costs, capped by their income). Their savings of ${money(p.savings)} stay theirs. You agreed to keep it that way.`);r.fatigue.money=h.day;return true;}
 if(topic==='purchase'){const big=HOMES.filter(x=>!l.homes[x.id]&&x.cost>0)[0];bump(p,{trust:2});note(`${p.name}: "${p.values.includes('planning')?'Show me the numbers and the runway, then yes.':'If we can still sleep at night, go for it.'}" (Asking before a major purchase keeps trust.)`);pp.flags.purchaseOk=h.day;return true;}
 if(topic==='hardship'){bump(p,{aff:4,trust:4,tension:-4});H().stress=clamp(H().stress-8,0,100);note(`${p.name}: "We\'ll get through it. Tell me what you need." Stress −8.`);return true;}
 return false;}
function separate(){const pp=PP(),p=partnerOf();if(!p||paused)return false;const married=pp.status==='married';const settle=married?Math.min(S.cash*.1,2e6):0;if(settle&&!spend(settle))return false;
 pp.status='separated';pp.partner=null;p.rel.tier='ex';p.home=false;pp.household=pp.household.filter(x=>x!==p.id);pp.exes.unshift(p.id);bump(p,{aff:-25,tension:10});p.rel.leaving=false;
 for(const k of kidsAtHome())if(k.parents.includes(p.id))addHistory(k,`${p.name} moved out. Still family.`);
 addHistory(p,married?'Divorced.':'Separated.');memory('separation',`Parted ways with ${p.name}`,`${married?'Divorce settlement '+money(settle)+'. ':''}You keep your homes and vehicles; ${p.name} keeps their savings. ${kidsAtHome().some(k=>k.parents.includes(p.id))?'The kids stay with you and keep both parents.':''}`,[p.id]);pp.status='single';return true;}
// ---------- children
function addChild(adopted){const pp=PP(),h=H(),p=partnerOf();const id='k'+(++pp.seq);const pool=CHILD_NAMES.filter(n=>!Object.values(pp.roster).some(x=>x.name===n));const name=pool[Math.floor(Math.random()*pool.length)]||'Kid';const seedFrom=p&&!adopted?[p.seed,[2,0,0,0,3,0]][Math.floor(Math.random()*2)]:[Math.floor(Math.random()*6),Math.floor(Math.random()*5),Math.floor(Math.random()*6),Math.floor(Math.random()*3),Math.floor(Math.random()*7),0];
 const k={id,kind:'child',name,gender:['f','m','n'][Math.floor(Math.random()*3)],stage:adopted?'child':'infant',born:h.day-(adopted?STAGES.child[0]*SEASON:0),temperament:TEMPERAMENTS[Math.floor(Math.random()*5)],interests:[KID_INTERESTS[Math.floor(Math.random()*KID_INTERESTS.length)]],confidence:50,wellbeing:70,independence:adopted?15:0,expectations:'balanced',school:'public',seed:[seedFrom[0],Math.floor(Math.random()*5),seedFrom[2],seedFrom[3],Math.floor(Math.random()*7),0],adopted,parents:p?['you',p.id]:['you'],outcome:'',home:true,rel:freshRel(),job:'',income:0,path:'',traits:[],values:[],avail:[0,1,2,3,4,5,6],ties:{},goalIndex:0,goalProgress:0,milestone:false,savings:0,dateable:false,joined:h.day,age:0,children:[],interestsShown:0,met:true};
 k.rel.met=true;k.rel.affection=40;k.rel.trust=40;k.rel.tier='family';pp.roster[id]=k;pp.order.push(id);pp.household.push(id);if(p)p.children.push(id);
 memory('child',`${name} joined the family`,`${adopted?'You adopted '+name+', a '+k.temperament+' kid who loves '+k.interests[0]+'.':name+' arrived. '+(p?p.name+' and you':'You')+' are parents now.'} Household costs rise by about ${money(childCost(k)*DAY)}/day.`,[id,...(p?[p.id]:[])]);return k;}
function childCost(k,s=S){const t=spendTier(s);return t.food*.6+(k.school==='private'?.15:0)+(k.stage==='infant'?.04:0);}
function familyExpenses(s=S){const x=[];const p=partnerOf(s);if(p&&livingTogether(s))x.push(['family','Food & essentials · '+p.name.split(' ')[0],spendTier(s).food*.8]);for(const k of kidsAtHome(s))x.push(['family',`${k.name} · ${k.school==='private'?'private school, ':''}essentials`,childCost(k,s)]);return x;}
function partnerShare(s=S){return .45;}
function partnerContribution(s=S){const p=partnerOf(s);if(!p||!livingTogether(s))return 0;const gross=houseExpensesGross(s).reduce((n,e)=>n+e[2],0);return Math.min(p.income*.6,gross*partnerShare(s));}
function kidStage(k){const seasons=Math.floor((H().day-k.born)/SEASON);return seasons>=STAGES.adult[0]?'adult':seasons>=STAGES.teen[0]?'teen':seasons>=STAGES.child[0]?'child':'infant';}
function parentAction(id,act){const k=person(id);if(!k||k.kind!=='child'||paused)return false;const r=k.rel;
 if(act==='support'){const c=Math.ceil(Math.max(20,clickPay()*3));if(!spend(c))return false;k.confidence=clamp(k.confidence+4,0,100);bump(k,{aff:4,trust:2});if(k.interests.length<3&&Math.random()<.3){const n=KID_INTERESTS.filter(i=>!k.interests.includes(i));k.interests.push(n[Math.floor(Math.random()*n.length)]);note(`${k.name} discovered ${k.interests.at(-1)}.`);}note(`You supported ${k.name}\'s ${k.interests[0]}. Confidence +4.`);}
 else if(act==='time'){if(r.fatigue.time===H().day){note(`You\'ve already spent today with ${k.name}.`);return true;}r.fatigue.time=H().day;bump(k,{aff:5,trust:3});k.wellbeing=clamp(k.wellbeing+3,0,100);note(`An afternoon with ${k.name}. ${k.temperament==='shy'?'Quiet, but they leaned in.':'They talked the whole time.'}`);}
 else if(act==='expect'){k.expectations=k.expectations==='gentle'?'balanced':k.expectations==='balanced'?'high':'gentle';note(`Expectations for ${k.name}: ${k.expectations}. ${k.expectations==='high'?'Pushes confidence up for bold kids, down for sensitive ones.':k.expectations==='gentle'?'Easy on wellbeing, slower on independence.':'A middle path.'}`);}
 else if(act==='school'){k.school=k.school==='public'?'private':'public';note(`${k.name} now attends ${k.school} school. ${k.school==='private'?'+'+money(.15*DAY)+'/day. Money widens options; attention still matters more.':'Costs drop.'}`);}
 else if(act==='future'){if(k.stage!=='teen'&&k.stage!=='adult')return false;bump(k,{trust:3});k.independence=clamp(k.independence+5,0,100);note(`${k.name}: "${k.confidence>=60?'I think I know what I want. Will you back me?':'I don\'t know yet. Is that okay?'}"`);}
 else return false;addHistory(k,act==='time'?'Time together.':act==='support'?'You backed their interest.':act==='future'?'Talked about the future.':'Household expectations changed.');return true;}
function childSeason(k){const r=k.rel,h=H();const stage=kidStage(k);
 // temperament × expectations
 if(k.expectations==='high')k.confidence=clamp(k.confidence+(k.temperament==='bold'?3:k.temperament==='sensitive'?-4:-1),0,100);
 if(k.expectations==='gentle')k.wellbeing=clamp(k.wellbeing+2,0,100);
 if(r.lastContact<h.day-SEASON)k.wellbeing=clamp(k.wellbeing-4,0,100);else k.wellbeing=clamp(k.wellbeing+2,0,100);
 if(h.arrears>0)k.wellbeing=clamp(k.wellbeing-3,0,100);if(H().stress>=75)k.wellbeing=clamp(k.wellbeing-2,0,100);
 if(stage==='teen')k.independence=clamp(k.independence+6,0,100);
 if(stage!==k.stage){k.stage=stage;queueEvent(stage==='child'?'kid-school':stage==='teen'?'kid-teen':'kid-adult',k.id);}
 else if(stage==='child'&&Math.random()<.5)addPlan(k.id,'celebrate','duty',h.day+2+Math.floor(Math.random()*4),`${k.name}\'s school event`);
 else if(stage==='teen'&&k.confidence<40&&k.expectations==='high'&&Math.random()<.6)queueEvent('kid-pressure',k.id);
 else if((stage==='child'||stage==='teen')&&Math.random()<.35)queueEvent('kid-situation',k.id);}
function adultOutcome(k){const biz=BUSINESSES.find(b=>S.business[b.id]&&({cooking:'culinary',building:'trades',science:'tech',games:'tech',drawing:'creative',music:'creative',reading:'finance',animals:'medicine',sport:'medicine',nature:'culinary'}[k.interests[0]]===b.path));const bond=k.rel.affection;
 if(k.confidence>=65&&k.independence>=50)return {id:'university',text:`${k.name} got into a university across the country and is leaving with a suitcase and a plan.`,leaves:true};
 if(biz&&bond>=60&&k.wellbeing>=50)return {id:'together',text:`${k.name} wants to work with you at ${biz.name.toLowerCase()} — as a colleague, not an heir.`,leaves:false};
 if(bond<40)return {id:'distance',text:`${k.name} is moving out and keeping things polite. There\'s history to work through.`,leaves:true};
 if(k.confidence<40)return {id:'nearby',text:`${k.name} is staying nearby, figuring it out one job at a time. They still come for dinner.`,leaves:true};
 return {id:'career',text:`${k.name} took a job in the city and found a flat with friends. Sunday calls, mostly.`,leaves:true};}
// ---------- planner
function addPlan(personId,activity,type,day,label='',recurring=null){const pp=PP();if(pp.plans.length>=10)return null;if(pp.plans.some(c=>c.day===day&&c.person===personId))return null;const c={id:'c'+(++pp.seq),day,person:personId,activity,type,label:label||ACTIVITIES[activity].name,recurring,moved:0};pp.plans.push(c);return c;}
function addRoutine(personId,activity,wd){const pp=PP();if(pp.routines.some(r=>r.person===personId&&r.activity===activity))return false;if(pp.routines.length>=6)return false;pp.routines.push({person:personId,activity,weekday:wd});const d=H().day+((wd-weekday()+7)%7||7);addPlan(personId,activity,'plan',d,ACTIVITIES[activity].name+' (weekly)',wd);return true;}
function planConflict(day){return PP().plans.find(c=>c.day===day);}
function keepCommitment(c,go){const pp=PP(),p=person(c.person);if(!p)return;const r=p.rel;const w=c.type==='duty'?2:c.type==='promise'?1.5:1;
 if(go){r.kept++;const repair=r.repairSince>=0;bump(p,{aff:3*w,trust:(repair?6:3)*w,tension:-(repair?6:2)*w});if(repair&&r.tension<20){r.repairSince=-1;r.apologies=0;memory('repair',`Made things right with ${p.name}`,`You said sorry, then showed up. ${p.name} noticed.`,[p.id]);}addHistory(p,`Kept: ${c.label}.`);if(p.kind==='child'){p.confidence=clamp(p.confidence+3,0,100);p.wellbeing=clamp(p.wellbeing+2,0,100);}}
 else{if(c.type==='plan'){bump(p,{aff:-1});addHistory(p,`Skipped: ${c.label}.`);}else{r.broken++;bump(p,{trust:-4*w,tension:6*w,aff:-2*w});addHistory(p,`${c.type==='duty'?'Missed':'Broke a promise'}: ${c.label}.`);if(p.kind==='child'){p.confidence=clamp(p.confidence-4,0,100);}if(r.broken>=3&&r.broken>r.kept)queueEvent('broken',p.id);}}
 pp.plans=pp.plans.filter(x=>x.id!==c.id);if(c.recurring!==null&&go)addPlan(c.person,c.activity,'plan',c.day+7,c.label,c.recurring);}
// ---------- household activities (At home)
const HOME_ACTS={
 meal:{name:'Shared meal',need:()=>true,cost:()=>Math.ceil(Math.max(6,clickPay())),desc:'Everyone at the table. Works in any home.',pose:'eat'},
 film:{name:'Film night',need:()=>hasSlot('seating'),cost:()=>0,desc:'Needs seating in this room.',pose:'sit'},
 cook:{name:'Cook together',need:()=>true,cost:()=>Math.ceil(Math.max(4,clickPay()*.7)),desc:'A meal made by more than one pair of hands.',pose:'cook'},
 garden:{name:'Garden',need:()=>activeHome().rooms>=5||S.hobbies.garden>0,cost:()=>0,desc:'Needs a garden, or the gardening hobby.',pose:'water'},
 music:{name:'Practice music',need:()=>S.hobbies.music>0||kidsAtHome().some(k=>k.interests.includes('music')),cost:()=>0,desc:'Needs the music hobby, or a musical kid.',pose:'music'},
 read:{name:'Read or study together',need:()=>hasSlot('storage')||S.items.desk,cost:()=>0,desc:'Needs a bookshelf piece or a study desk.',pose:'read'},
 host:{name:'Host a friend',need:()=>metPeople().some(p=>!p.home&&['friend','close'].includes(tierOf(p))),cost:()=>Math.ceil(Math.max(10,clickPay()*1.5)),desc:'Invite a friend over.',pose:'sit'},
 talk:{name:'Private conversation',need:()=>PP().household.length>0,cost:()=>0,desc:'One person, no distractions.',pose:'talk'},
};
function hasSlot(slot){const l=syncLife(S),h=activeHome();return Object.values(l.layouts[h.id]||{}).some(r=>r[slot]);}
function homeActivity(id){const a=HOME_ACTS[id],pp=PP();if(!a||!a.need()||paused)return false;if(pp.flags['act:'+id]===H().day){toast('Already did that today. Tomorrow.');return false;}const c=a.cost();if(c&&!spend(c)){toast('Not enough cash.');return false;}pp.flags['act:'+id]=H().day;pp.flags.lastAct=id;
 const members=pp.household.map(id=>person(id)).filter(Boolean);let text='';
 if(id==='host'){const f=metPeople().filter(p=>!p.home&&['friend','close'].includes(tierOf(p)))[0];bump(f,{aff:5,trust:2});f.rel.lastContact=H().day;addHistory(f,'Came over.');text=`${f.name} came over${members.length?' and met everyone':''}.`;if(members.length&&!pp.flags['host:'+f.id]){pp.flags['host:'+f.id]=true;memory('host',`${f.name} at ${activeHome().name.toLowerCase()}`,`First time ${f.name} saw where you live.`,[f.id,...members.map(m=>m.id)]);}}
 else if(id==='talk'){const m=members.find(x=>x.rel.tension>=10)||members[0];bump(m,{tension:-4,trust:2,aff:2});text=`A quiet word with ${m.name}. ${m.rel.tension>=30?'It helped, a little.':'Nice to just talk.'}`;}
 else{for(const m of members){bump(m,{aff:id==='meal'?3:2,tension:-1});m.rel.lastContact=H().day;if(m.kind==='child'){m.wellbeing=clamp(m.wellbeing+2,0,100);if(id==='music'&&m.interests.includes('music'))m.confidence=clamp(m.confidence+2,0,100);if(id==='read')m.confidence=clamp(m.confidence+1,0,100);}}H().stress=clamp(H().stress-3,0,100);text=`${a.name}${members.length?' with '+members.map(m=>m.name.split(' ')[0]).join(', '):' on your own'}. Stress −3.`;
  if(members.length>=2&&!pp.flags.firstHoliday&&id==='meal'&&(S.items.travel||season()%4===3)){pp.flags.firstHoliday=true;memory('holiday','First family holiday',`A long table, ${members.map(m=>m.name.split(' ')[0]).join(' and ')}, and nowhere to be.`,members.map(m=>m.id));}}
 note(text);return true;}
// ---------- daily / seasonal simulation (called from houseDay; never offline)
function peopleDay(){const pp=PP(),h=H();
 // meet someone new, naturally
 if(h.day-pp.lastMeet>=(pp.order.length?4:2)&&Math.random()<(pp.order.length?.35:.8)&&h.day>=2){const c=meetCandidate();if(c)queueEvent('meet',c.id);}
 // commitments due today
 for(const c of pp.plans)if(c.day===h.day)queueEvent('commitment',c.id);
 // partner / friends: neglect only from active play, never from absence
 for(const p of metPeople()){const r=p.rel,t=tierOf(p);
  if(p.kind==='child')continue;
  if(p.home&&h.day-r.lastContact>=12&&h.load>2.2&&r.lastNeglect<h.day-20){r.lastNeglect=h.day;queueEvent('neglect',p.id);}
  if(!p.home&&t==='close'&&h.day-r.lastContact>=25&&r.lastNeglect<h.day-40){r.lastNeglect=h.day;queueEvent('friend-taken',p.id);}
  if(!p.home&&h.day-r.lastContact>20&&r.affection>25)r.affection-=.15; // slow drift, floors at friend level
  if(p.home&&H().stress>=75){r.tension=clamp(r.tension+.4,0,100);if(pp.flags.spillDay!==undefined&&h.day-pp.flags.spillDay>=3&&!pp.flags.spillSeen){pp.flags.spillSeen=true;queueEvent('spill',p.id);}else if(pp.flags.spillDay===undefined)pp.flags.spillDay=h.day;}else{delete pp.flags.spillDay;pp.flags.spillSeen=false;}
  if(p.home&&h.arrears>0&&h.day-h.arrearsSince>=5&&!pp.flags['strain:'+p.id]){pp.flags['strain:'+p.id]=true;queueEvent('strain',p.id);}if(h.arrears===0)delete pp.flags['strain:'+p.id];
  if(p.home&&r.tension>=40&&r.repairSince<0&&r.tension<70)r.tension=clamp(r.tension-.2,0,100); // small natural cooling when not severe
  // leaving is telegraphed a whole season ahead
  if(p.home&&r.tension>=85&&r.trust<25){if(!r.leaving){r.leaving=true;r.leavingSince=h.day;note(`${p.name} is thinking seriously about leaving. Listen, apologise, keep promises, or agree to part ways.`);}else if(h.day-r.leavingSince>=SEASON)queueEvent('leaving',p.id);}else if(r.leaving&&(r.tension<70||r.trust>=35)){r.leaving=false;note(`${p.name} has stopped talking about leaving.`);}
  if(p.kind==='adult'&&p.milestone===false&&Math.random()<.04){p.goalProgress=Math.min(3,p.goalProgress+1);if(p.goalProgress>=3){p.milestone=true;if(t!=='acquaintance')note(`${p.name} is about to ${goalOf(p).text.toLowerCase()}. Be there.`);}}
  if(p.home&&livingTogether()&&p.id===pp.partner){p.savings=num(p.savings+(p.income-partnerContribution())*DAY*.5);}
 }
 // seasons
 const s=season();if(s>pp.season){pp.season=s;for(const k of allKids())if(k.home)childSeason(k);for(const p of metPeople())if(p.kind==='adult'&&!p.home&&p.rel.reduced>=0&&p.rel.reduced+SEASON<=h.day){p.rel.reduced=-1;note(`${p.name} is open to plans again.`);}
  if(livingTogether()&&Math.random()<.3&&!pp.flags['future:'+s])queueEvent('future',pp.partner);
  if(h.arrears===0&&pp.flags.hardship&&pp.household.length){delete pp.flags.hardship;memory('recovery','Back on solid ground',`The bills are paid and the house is calm again. ${pp.household.map(id=>person(id)?.name.split(' ')[0]).join(', ')} stuck with you.`,pp.household.slice());}
  if(h.arrears>0&&pp.household.length)pp.flags.hardship=true;}
}
function peopleHomeMoved(){const pp=PP();if(!pp.household.length)return;const p=partnerOf();if(p&&livingTogether()&&pp.flags.purchaseOk!==undefined&&H().day-pp.flags.purchaseOk<=15){bump(p,{aff:4,trust:2});}else if(p&&livingTogether()){queueEvent('moving',p.id);}memory('move',`Moved to ${activeHome().name.toLowerCase()}`,`New keys, same people: ${pp.household.map(id=>person(id)?.name.split(' ')[0]).join(', ')}.`,pp.household.slice());}
function supportBonus(s=S){let b=0;for(const id of PP(s).household){const p=person(id,s);if(p&&p.rel.affection>=60&&p.rel.tension<30)b+=.004;}return Math.min(.012,b);}
function conflictStress(s=S){let u=0;for(const id of PP(s).household){const p=person(id,s);if(p&&p.rel.tension>=50)u+=.004;}return Math.min(.01,u);}
// ---------- events
const P_EVENTS={
 meet:{title:'Someone new',scene:2,cause:id=>{const c=CAST.find(x=>x.id===id);return c?`${c.name}, ${c.job.toLowerCase()}. ${c.bio} ${c.line}`:'';},options:id=>[{c:'hello',label:'Say hello',desc:'Add them to your people.'},{c:'later',label:'Not today',desc:'You\'ll cross paths again.'}]},
 commitment:{title:'Today\'s plan',scene:7,cause:id=>{const c=PP().plans.find(x=>x.id===id),p=c&&person(c.person);return c?`${c.label} with ${p.name} is today. ${c.type==='duty'?'This one matters to them.':c.type==='promise'?'You promised.':'An optional plan.'}${c.moved?' Already rescheduled once.':''}`:'';},
  options:id=>{const c=PP().plans.find(x=>x.id===id);if(!c)return [{c:'later',label:'Close'}];const cost=ACTIVITIES[c.activity].cost(person(c.person));return [{c:'go',label:'Go'+(cost?' · '+money(cost):''),cost:cost||null,desc:'Keep it.'},{c:'move',label:c.moved?'Reschedule again (counts as skipped)':'Reschedule +2 days',desc:c.type==='plan'?'No harm.':'Explaining in advance is fine once.'},{c:'skip',label:c.type==='plan'?'Skip it':'Cancel (breaks the '+(c.type==='duty'?'responsibility':'promise')+')',desc:c.type==='plan'?'They\'ll understand.':'Trust will take a hit.'}];}},
 neglect:{title:'Fitting into the gaps',scene:7,cause:id=>`${person(id)?.name} hasn\'t had real time with you in ${H().day-person(id).rel.lastContact} days while you\'ve been working flat out. "I feel like I\'m fitting into the gaps of your work."`,options:()=>[{c:'listen',label:'Listen and plan an evening',desc:'Adds a promise to your planner. Keep it and trust rebuilds.'},{c:'sorry',label:'Apologise',desc:'A start. Words alone won\'t close it.'},{c:'brush',label:'"It\'s a busy season."',desc:'Tension rises.'}]},
 'friend-taken':{title:'A friend, taken for granted',scene:2,cause:id=>`${person(id)?.name} hasn\'t heard from you in ${H().day-person(id).rel.lastContact} days. They\'ve stopped suggesting things.`,options:()=>[{c:'listen',label:'Reach out and make a plan',desc:'Adds a plan for their next free day.'},{c:'brush',label:'Let it drift',desc:'They take some space for a season.'}]},
 broken:{title:'A pattern of broken promises',scene:7,cause:id=>`${person(id)?.name}: "You\'ve broken ${person(id).rel.broken} promises now. I don\'t know what your word means."`,options:()=>[{c:'sorry',label:'Own it and apologise',desc:'Opens a repair window. Only kept promises close it.'},{c:'counsel',label:'Suggest counselling · '+money(Math.ceil(Math.max(80,clickPay()*12))),cost:Math.ceil(Math.max(80,clickPay()*12)),desc:'Three sessions lower tension steadily.'},{c:'brush',label:'"You\'re overreacting."',desc:'Serious damage.'}]},
 strain:{title:'Money at the kitchen table',scene:1,cause:id=>`${person(id)?.name}: "The bills are ${money(H().arrears)} overdue and you haven\'t said a word. Can we make a plan?"`,options:()=>[{c:'plan',label:'Make a plan together',desc:'Trust rises now, more if the bills are cleared within a week.'},{c:'hide',label:'"I\'ve got it handled."',desc:'Tension rises.'}]},
 moving:{title:'You moved without asking',scene:1,cause:id=>`${person(id)?.name}: "We live together and I found out about the move from the boxes."`,options:()=>[{c:'sorry',label:'Apologise and talk it through',desc:'Tension partly eases; ask next time.'},{c:'insist',label:'"It was the right call."',desc:'Tension rises.'}]},
 future:{title:'What we\'re building',scene:7,cause:id=>{const p=person(id);return `${p?.name} wants to talk about the future: ${p.values.includes('family')?'whether kids are part of it':p.values.includes('ambition')?'the café dream and what it costs':p.values.includes('freedom')?'taking a year to travel':'where you\'ll live in five years'}.`;},options:()=>[{c:'yes',label:'"Let\'s plan it together."',desc:'Affection and trust rise.'},{c:'time',label:'"I need time to think."',desc:'Fine once. A pattern adds tension.'},{c:'no',label:'"That\'s not what I want."',desc:'Honest. Tension rises a little; they may adjust or not.'}]},
 spill:{title:'Bringing the day home',scene:1,cause:id=>`${person(id)?.name}: "You\'ve been at ${Math.round(H().stress)} stress for days and it\'s landing on us."`,options:()=>[{c:'rest',label:'Take a quiet evening now',desc:'Free. Stress −15, tension eases.'},{c:'talk',label:'Talk it through',desc:'Tension eases; stress −5.'},{c:'counsel',label:'Counselling · '+money(Math.ceil(Math.max(80,clickPay()*12))),cost:Math.ceil(Math.max(80,clickPay()*12))},{c:'brush',label:'"I\'m fine."'}]},
 leaving:{title:'A hard conversation',scene:1,cause:id=>`${person(id)?.name} has been thinking about leaving for a season. Tension is ${Math.round(person(id).rel.tension)}, trust ${Math.round(person(id).rel.trust)}. "I can\'t keep doing this. Either we change it, or I go."`,options:id=>{const p=person(id);return [{c:'counsel',label:'Ask them to try counselling · '+money(Math.ceil(Math.max(80,clickPay()*12))),cost:Math.ceil(Math.max(80,clickPay()*12)),desc:'They agree if trust is above 15. Tension −20.'},{c:'part',label:'Agree to part ways',desc:`Amicable. ${PP().status==='married'?'Settlement '+money(Math.min(S.cash*.1,2e6))+'. ':''}You keep your homes and vehicles.`},{c:'plead',label:'"Please stay."',desc:'They stay one more season if affection is above 50; otherwise they leave.'}];}},
 'kid-school':{title:'First day of school',scene:2,cause:id=>`${person(id)?.name} starts school. ${person(id).temperament==='shy'?'Nervous, holding your hand a bit too tight.':'Already asking what\'s for lunch.'}`,options:()=>[{c:'walk',label:'Walk them in',desc:'Confidence +5.'},{c:'public',label:'Public school',desc:'Free.'},{c:'private',label:'Private school · '+money(.15*DAY)+'/day',desc:'More options; attention still matters more.'}]},
 'kid-teen':{title:'Not a kid anymore',scene:1,cause:id=>`${person(id)?.name} is a teenager. Doors close. Music gets louder. They\'re into ${person(id).interests.join(' and ')}.`,options:()=>[{c:'space',label:'Give them space',desc:'Independence rises.'},{c:'talk',label:'Talk about what they want',desc:'Trust rises.'}]},
 'kid-pressure':{title:'Feeling pressured',scene:1,cause:id=>`${person(id)?.name}: "Nothing I do is enough for you." Confidence is ${Math.round(person(id).confidence)} under high expectations.`,options:()=>[{c:'ease',label:'Ease off',desc:'Expectations → balanced. Wellbeing recovers.'},{c:'hold',label:'"I expect this because I believe in you."',desc:'Works for bold kids. Hurts sensitive ones.'}]},
 'kid-situation':{title:'A difficult day',scene:2,cause:id=>{const k=person(id);return `${k?.name} ${k.temperament==='bold'?'got into a fight standing up for a friend':k.temperament==='sensitive'?'came home in tears over a friendship':k.temperament==='shy'?'is being left out at school':'failed a test they cared about'}.`;},options:()=>[{c:'help',label:'Sit with them and help',desc:'Wellbeing and trust rise.'},{c:'fix',label:'Fix it for them',desc:'Wellbeing rises; confidence doesn\'t.'},{c:'busy',label:'"Not now."',desc:'Trust falls.'}]},
 'kid-adult':{title:'Grown',scene:2,cause:id=>{const k=person(id);return `${k?.name} is an adult. ${adultOutcome(k).text}`;},options:id=>{const o=adultOutcome(person(id));return [{c:'bless',label:o.leaves?'Help them move':'Welcome them aboard',desc:'Their choice, your support.'},{c:'ask',label:'Ask them to stay a while',desc:'They stay a season if the bond is strong.'}];}},
};
const P_PRIORITY={leaving:5,commitment:3,broken:2,strain:2,'kid-adult':2,'kid-teen':2,'kid-school':2,spill:1,neglect:1,moving:1,future:1,'kid-pressure':1,'kid-situation':1,'friend-taken':1,meet:0};
function resolvePeopleEvent(t,id,c){const pp=PP(),h=H();const p=person(id);
 if(t==='meet'){if(c==='hello')meetPerson(id);else pp.lastMeet=h.day;return true;}
 if(t==='commitment'){const cm=pp.plans.find(x=>x.id===id);if(!cm)return true;const q=person(cm.person);if(c==='go'){const cost=ACTIVITIES[cm.activity].cost(q);if(cost&&!spend(cost))return false;const text=ACTIVITIES[cm.activity].apply(q,q.rel);q.rel.fatigue[cm.activity]=h.day;q.rel.lastContact=h.day;keepCommitment(cm,true);if(cm.label==='Visiting hours'&&S.city?.prison)S.city.prison.visits++;note(text);}else if(c==='move'){if(cm.moved>=1)keepCommitment(cm,false);else{cm.moved++;cm.day=h.day+2;}}else keepCommitment(cm,false);return true;}
 if(!p)return true;const r=p.rel;
 if(t==='neglect'||t==='friend-taken'){if(c==='listen'){bump(p,{tension:-4,trust:1});addPlan(p.id,'coffee','promise',nextFreeDay(p,h.day+1),'Evening together (promised)');}else if(c==='sorry')interact(p.id,'apologize');else{bump(p,{tension:t==='neglect'?8:4,aff:-3});if(t==='friend-taken')r.reduced=h.day;}return true;}
 if(t==='broken'){if(c==='sorry')interact(p.id,'apologize');else if(c==='counsel'){r.counsel++;bump(p,{tension:-12,trust:4});}else bump(p,{tension:15,trust:-6,aff:-5});return true;}
 if(t==='strain'){if(c==='plan'){bump(p,{trust:5,tension:-4});pp.flags.strainPlan=h.day;}else bump(p,{tension:8,trust:-3});return true;}
 if(t==='moving'){if(c==='sorry')bump(p,{tension:4,trust:-1});else bump(p,{tension:12,trust:-4});return true;}
 if(t==='future'){pp.flags['future:'+season()]=true;if(c==='yes')bump(p,{aff:6,trust:4,tension:-3});else if(c==='time'){pp.flags.futureTime=(pp.flags.futureTime||0)+1;if(pp.flags.futureTime>=3)bump(p,{tension:6});}else bump(p,{tension:5,trust:1});return true;}
 if(t==='spill'){if(c==='rest'){h.stress=clamp(h.stress-15,0,100);h.fx.restDay=h.day;bump(p,{tension:-6});}else if(c==='talk'){h.stress=clamp(h.stress-5,0,100);bump(p,{tension:-5,trust:2});}else if(c==='counsel'){r.counsel++;bump(p,{tension:-12,trust:3});}else bump(p,{tension:5});return true;}
 if(t==='leaving'){if(c==='counsel'){if(r.trust<15){note(`${p.name}: "It\'s too late for that."`);return separate();}r.counsel++;bump(p,{tension:-20,trust:8});r.leaving=false;memory('repair',`${p.name} stayed`,`Counselling, and a real change. It wasn\'t over after all.`,[p.id]);}else if(c==='part'){return separate();}else{if(r.affection>50){r.leavingSince=h.day;note(`${p.name}: "One more season. Then I need to see it."`);}else return separate();}return true;}
 if(t==='kid-school'){if(c==='walk')p.confidence=clamp(p.confidence+5,0,100);if(c==='private')p.school='private';if(c==='public')p.school='public';memory('school',`${p.name} started school`,`${p.school==='private'?'Private':'Public'} school, a too-big backpack, and a wave from the gate.`,[p.id,...pp.household.filter(x=>x!==p.id)]);return true;}
 if(t==='kid-teen'){if(c==='space')p.independence=clamp(p.independence+10,0,100);else bump(p,{trust:6});memory('teen',`${p.name}, teenager`,`Doors, headphones, and opinions. Into ${p.interests.join(' and ')}.`,[p.id]);return true;}
 if(t==='kid-pressure'){if(c==='ease'){p.expectations='balanced';p.wellbeing=clamp(p.wellbeing+8,0,100);bump(p,{trust:4});}else{if(p.temperament==='bold')p.confidence=clamp(p.confidence+6,0,100);else{p.wellbeing=clamp(p.wellbeing-8,0,100);bump(p,{tension:8,trust:-3});}}return true;}
 if(t==='kid-situation'){if(c==='help'){p.wellbeing=clamp(p.wellbeing+6,0,100);p.confidence=clamp(p.confidence+3,0,100);bump(p,{trust:5,aff:3});}else if(c==='fix'){p.wellbeing=clamp(p.wellbeing+5,0,100);bump(p,{aff:2});}else{bump(p,{trust:-5,tension:4});p.wellbeing=clamp(p.wellbeing-3,0,100);}return true;}
 if(t==='kid-adult'){const o=adultOutcome(p);p.outcome=o.id;if(c==='ask'&&r.affection>=60&&o.leaves){p.born-=SEASON;note(`${p.name} stays another season.`);return true;}p.stage='adult';p.kind='child';p.age=18;p.job=o.id==='university'?'Student':o.id==='together'?'Works with you':o.id==='career'?'City job':o.id==='nearby'?'Finding their feet':'Keeping distance';if(o.leaves){p.home=false;pp.household=pp.household.filter(x=>x!==p.id);}r.tier='family';if(o.id==='distance')bump(p,{tension:20});memory(o.leaves?'moveout':'together',o.leaves?`${p.name} moved out`:`${p.name} joined you at work`,o.text,[p.id]);return true;}
 return true;}
// ---------- pixel portraits (procedural, identity-stable, no external art needed)
const SKIN=['#f5d5b8','#e8b894','#c98d63','#a3673f','#7a4a2b','#4e2f1c'];
const HAIRC=['#2b1b12','#5a3a1e','#a0623a','#e2c26b','#1b1b1b','#c9c9c9'];
const EYEC=['#2b1b12','#3a5f8a','#4f7a3e'];
const TOPC=['#c94f4f','#4f7ac9','#4fa072','#c98a3a','#8a5fc9','#3d3d3d','#d9c26b'];
function portraitSVG(p,opts={}){const [sk,hs,hc,ey,tp,ac]=p.seed;const st=p.kind==='child'?(p.stage==='adult'?'adult':p.stage):'adult';const mood=opts.mood||moodOf(p);const px=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;let s='';
 const skin=SKIN[sk%6],hair=HAIRC[hc%6],eye=EYEC[ey%3],top=TOPC[tp%7];const small=st==='infant',kid=st==='child',teen=st==='teen';
 const hx=small?5:kid?4:3,hy=small?7:kid?5:3,hw=small?6:kid?8:10,hh=small?6:kid?7:8; // head box
 s+=px(hx-1,hy+hh,hw+2,20-(hy+hh),top); // body
 if(!small)s+=px(hx+2,hy+hh-1,hw-4,1,skin); // neck
 s+=px(hx,hy,hw,hh,skin); // face
 // hair styles: 0 short,1 long,2 bun,3 curly,4 buzz
 if(hs%5===0)s+=px(hx-1,hy-1,hw+2,3,hair);else if(hs%5===1){s+=px(hx-1,hy-1,hw+2,3,hair);s+=px(hx-1,hy,1,hh+3,hair);s+=px(hx+hw,hy,1,hh+3,hair);}else if(hs%5===2){s+=px(hx-1,hy-1,hw+2,2,hair);s+=px(hx+hw-2,hy-3,3,3,hair);}else if(hs%5===3){s+=px(hx-2,hy-2,hw+4,4,hair);s+=px(hx-2,hy+2,1,2,hair);s+=px(hx+hw+1,hy+2,1,2,hair);}else s+=px(hx,hy-1,hw,1,hair);
 // eyes
 const ey1=hx+2,ey2=hx+hw-3,eyy=hy+Math.floor(hh/2);s+=px(ey1,eyy,1,1,eye)+px(ey2,eyy,1,1,eye);
 // brows by mood
 if(mood==='concern'){s+=px(ey1,eyy-1,2,1,hair)+px(ey2-1,eyy-1,2,1,hair);}else if(mood==='upset'){s+=px(ey1,eyy-2,1,1,hair)+px(ey1+1,eyy-1,1,1,hair)+px(ey2,eyy-2,1,1,hair)+px(ey2-1,eyy-1,1,1,hair);}
 // mouth
 const my=hy+hh-2;if(mood==='happy')s+=px(hx+3,my,hw-6,1,'#8a3b3b')+px(hx+2,my-1,1,1,'#8a3b3b')+px(hx+hw-3,my-1,1,1,'#8a3b3b');else if(mood==='upset')s+=px(hx+3,my,hw-6,1,'#8a3b3b')+px(hx+2,my+1,1,1,'#8a3b3b')+px(hx+hw-3,my+1,1,1,'#8a3b3b');else s+=px(hx+3,my,hw-6,1,'#8a3b3b');
 if(ac%3===1&&!small)s+=`<rect x="${ey1-1}" y="${eyy-1}" width="3" height="3" fill="none" stroke="#222" stroke-width=".5"/><rect x="${ey2-1}" y="${eyy-1}" width="3" height="3" fill="none" stroke="#222" stroke-width=".5"/>`;if(ac%3===2)s+=px(hx-1,eyy+1,1,1,'#e2c26b')+px(hx+hw,eyy+1,1,1,'#e2c26b');
 if(teen)s+=px(hx-1,hy+hh,hw+2,1,'#222'); // hoodie line
 return `<svg class="portrait ${opts.cls||''}" viewBox="0 0 16 20" shape-rendering="crispEdges" role="img" aria-label="${esc(p.name)}">${s}</svg>`;}
function moodOf(p){const r=p.rel;if(r.leaving||r.tension>=60)return 'upset';if(r.tension>=30)return 'concern';if(r.affection>=55)return 'happy';return 'neutral';}
function spriteSVG(p,pose){const px=(x,y,w,h,c)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;let prop='';if(pose==='read')prop=px(2,13,5,3,'#e9d9b0')+px(2,13,5,1,'#b9a27a');if(pose==='cook')prop=px(9,12,5,2,'#444')+px(13,12,3,1,'#8a5a2b');if(pose==='water')prop=px(10,13,4,3,'#4f7ac9')+px(13,12,2,1,'#4f7ac9');if(pose==='music')prop=px(10,10,2,6,'#8a5a2b')+px(9,15,4,3,'#c98a3a');if(pose==='draw')prop=px(3,14,6,3,'#fff')+px(4,15,2,1,'#c94f4f');if(pose==='eat')prop=px(3,15,10,1,'#e9d9b0')+px(6,14,4,1,'#c94f4f');return `<div class="sprite ${pose||'stand'} ${p.kind==='child'?p.stage:'adult'}" title="${esc(p.name)}">${portraitSVG(p,{cls:'sprite-body'})}<svg class="prop" viewBox="0 0 16 20" shape-rendering="crispEdges" aria-hidden="true">${prop}</svg><span class="sprite-name">${esc(p.name.split(' ')[0])}</span></div>`;}
// ---------- UI
function personCard(p){const t=tierOf(p);return `<button class="person-card" data-action="ppl-open" data-id="${p.id}"><span class="person-portrait">${portraitSVG(p)}</span><span class="person-meta"><strong>${esc(p.name)}</strong><small>${p.kind==='child'?STAGES[p.stage][1]+' · '+(p.home?'at home':'moved out'):esc(p.job)}</small><span class="tag">${TIER_LABEL[t]}</span></span></button>`;}
function renderHomeInterior(){const pp=PP(),l=syncLife(S),h=activeHome(),room=l.layouts[h.id]?.[Math.min(l.room,h.rooms-1)]||{},members=pp.household.map(id=>person(id)).filter(Boolean),last=pp.flags.lastAct,lastDay=pp.flags['act:'+last];const pose=lastDay===H().day&&HOME_ACTS[last]?HOME_ACTS[last].pose:'stand';
 const pieces=['storage','lighting','seating','accent'].map(slot=>{const i=DECOR.find(i=>i.id===room[slot]);return i?`<div class="int-piece" style="--tint:${i.color}">${lifeArt('decor',i)}<small>${esc(i.name)}</small></div>`:'';}).join('');
 const sprites=[{id:'you',name:'You',kind:'adult',stage:'adult',seed:[2,0,0,1,1,0],rel:freshRel()},...members].map((m,i)=>{const pz=i===0?pose:(pose==='talk'?'stand':pose==='eat'?'eat':m.kind==='child'&&pose==='read'?'draw':pose);return spriteSVG(m,pz);}).join('');
 const acts=Object.entries(HOME_ACTS).map(([id,a])=>{const ok=a.need(),done=pp.flags['act:'+id]===H().day,c=a.cost();return `<button class="btn ${done?'ghost':''}" data-action="ppl-home" data-id="${id}" ${!ok||done?'disabled data-locked="true"':''} ${c?`data-cost="${c}"`:''} title="${esc(a.desc)}">${a.name}${c?' · '+money(c):''}${done?' ✓':''}</button>`;}).join('');
 return `<section class="interior" style="--wall:${h.color}"><div class="interior-scene" role="img" aria-label="${esc(h.name)} interior with ${members.length?members.map(m=>m.name).join(', '):'just you'}"><div class="int-wall"></div><div class="int-window"></div><div class="int-pieces">${pieces||'<div class="int-empty">An empty room. Decorate to make it yours.</div>'}</div><div class="int-floor"></div><div class="int-people">${sprites}</div><div class="int-caption"><span>${esc(ROOMS[Math.min(l.room,h.rooms-1)])} · ${members.length?members.length+1+' at home':'Just you'}</span><span>${lastDay===H().day&&HOME_ACTS[last]?HOME_ACTS[last].name+' today':'A quiet moment'}</span></div></div><div class="int-acts">${acts}</div><p class="small muted">Furnishings unlock activities and change the scene. One of each activity per game day. Modest homes support every essential activity.</p></section>`;}
function renderPeople(){const pp=PP(),met=metPeople(),open=pp.flags.open&&person(pp.flags.open);if(open)return renderProfile(open);
 const groups=[['HOUSEHOLD',met.filter(p=>p.home)],['PARTNER & FAMILY',met.filter(p=>!p.home&&['dating','ex','family'].includes(tierOf(p)))],['FRIENDS',met.filter(p=>!p.home&&['friend','close'].includes(tierOf(p)))],['ACQUAINTANCES',met.filter(p=>!p.home&&tierOf(p)==='acquaintance')]];
 const unmet=CAST.filter(c=>!pp.roster[c.id].rel.met).length;
 return `<div class="life-section-intro"><h2>The people in your life.</h2><p>${met.length?`${met.length} people, ${pp.household.length} at home. `:'You haven\'t met anyone yet. '}${unmet?`${unmet} more to meet through work, hobbies and the neighbourhood.`:'You know everyone on the street.'} Seasons pass every ${SEASON} game days; nothing changes while you\'re away.</p></div>${groups.filter(g=>g[1].length).map(([t,list])=>`<div class="section-title"><h3>${t}</h3></div><div class="people-grid">${list.map(personCard).join('')}</div>`).join('')||'<div class="empty">Keep working, pick up a hobby, or visit the city. Someone will say hello.</div>'}${renderTree()}`;}
function renderProfile(p){const pp=PP(),r=p.rel,t=tierOf(p),c=CAST.find(x=>x.id===p.id),free=freeToday(p),isPartner=pp.partner===p.id;
 const what=p.kind==='child'?`Loves ${p.interests.join(', ')}. ${p.temperament[0].toUpperCase()+p.temperament.slice(1)} by nature. ${p.stage==='adult'?'':'Expectations at home: '+p.expectations+'. School: '+p.school+'.'}`:`Cares about ${p.values.join(' and ')}. Into ${p.interests.map(i=>INTERESTS[i]||i).join(', ').toLowerCase()}.${shared(p).length?' You share '+INTERESTS[shared(p)[0]].toLowerCase()+'.':''}`;
 const plans=p.kind==='adult'?`Working on: ${goalOf(p).text.toLowerCase()} (${['just started','under way','close','ready'][p.goalProgress]}${p.milestone?' — celebrate it!':''}). Needs ${goalOf(p).need}.`:p.stage==='adult'?`${p.job}. ${p.outcome==='together'?'Working alongside you.':p.outcome==='distance'?'Keeping some distance.':'Building their own life.'}`:`Confidence ${p.confidence>=65?'high':p.confidence>=40?'steady':'shaky'}, wellbeing ${p.wellbeing>=65?'good':p.wellbeing>=40?'okay':'low'}, ${p.stage==='teen'?'independence growing':'still needs you around'}.`;
 const concern=r.leaving?'Thinking about leaving.':r.tension>=40?concernText(p):r.reduced>=0&&r.reduced+SEASON>H().day?'Taking some space for a season.':'';
 const ties=Object.entries(p.ties||{}).map(([id,how])=>{const q=person(id);return q?`${q.name.split(' ')[0]} (${how}${q.rel.met?'':', not met yet'})`:'';}).filter(Boolean);const fam=[];if(p.kind==='child'){fam.push('Parents: you'+(p.parents.filter(x=>x!=='you').map(id=>person(id)?', '+person(id).name:'').join('')||'')+(p.adopted?' (adopted)':''));}if(p.children?.length)fam.push('Children: '+p.children.map(id=>person(id)?.name).filter(Boolean).join(', '));if(p.family)fam.push(p.family);
 let actions='';
 if(p.kind==='child'&&p.stage!=='adult'){actions=[['time','Spend the afternoon'],['support','Support their '+p.interests[0]+' · '+money(Math.ceil(Math.max(20,clickPay()*3)))],['expect','Expectations: '+p.expectations],['school','School: '+p.school],...(p.stage==='teen'?[['future','Talk about the future']]:[])].map(([a,l])=>button(l,'ppl-parent',p.id+':'+a)).join('');}
 else{actions=Object.entries(ACTIVITIES).filter(([k])=>!(k==='celebrate'&&!p.milestone)&&!(k==='apologize'&&r.tension<5)&&!(k==='listen'&&r.tension<10)).map(([k,a])=>{const cost=a.cost(p);return button(a.name+(cost?' · '+money(cost):''),'ppl-act',p.id+':'+k,cost||null,a.inPerson&&!free);}).join('');
  actions+=button('Plan something','ppl-plan',p.id,null,false,'ghost');
  if(p.dateable&&!pp.partner&&['friend','close'].includes(t))actions+=button('Ask them out','ppl-ask',p.id,null,r.fatigue.ask>H().day-SEASON,'mint-btn');
  if(isPartner){const topics=pp.status==='dating'?[['movein','Talk about moving in']]:[['balance','Work-life balance'],['money','Shared expenses'],['purchase','A major purchase'],['hardship','Support each other'],...(pp.status==='together'?[['marry','Marriage']]:[]),['parent','Becoming parents'],['adopt','Adoption']];actions+=topics.map(([k,l])=>button(l,'ppl-discuss',k,null,false,'ghost')).join('');actions+=button('Separate…','ppl-separate','',null,false,'danger');}}
 return `<div class="profile"><div class="profile-head"><span class="profile-portrait">${portraitSVG(p,{cls:'big'})}</span><div><div class="eyebrow">${TIER_LABEL[t].toUpperCase()}${p.kind==='adult'?' · '+esc(p.job).toUpperCase():' · '+STAGES[p.stage][1].toUpperCase()}</div><h2>${esc(p.name)}</h2><p>${c?esc(c.bio):p.kind==='child'?esc(`${p.name} ${p.stage==='infant'?'is tiny and loud':p.stage==='child'?'draws on everything':p.stage==='teen'?'has opinions':'is grown'}.`):''}</p><p class="small">${esc(p.name.split(' ')[0])} ${feelText(p)}. ${free?'Free today.':'Busy today · free '+p.avail.map(d=>WEEKDAYS[d]).join(', ')+'.'}</p></div>${button('← All people','ppl-close','',null,false,'ghost')}</div>
 <div class="lhc-grid"><section class="panel"><div class="eyebrow">WHAT MATTERS TO THEM</div><p>${esc(what)}</p><p>${esc(plans)}</p>${ties.length||fam.length?`<p class="small muted">${[...fam,...ties].map(esc).join(' · ')}</p>`:''}${p.kind==='adult'&&isPartner&&livingTogether()?`<p class="small muted">Contributes ${money(partnerContribution()*DAY)}/day to the household. Own savings ${money(p.savings)} (not part of your net worth).</p>`:''}</section>
 <section class="panel"><div class="eyebrow">YOUR RELATIONSHIP</div><p>${esc(p.name.split(' ')[0])} ${feelText(p)}.${r.kept||r.broken?` Promises kept ${r.kept}, broken ${r.broken}.`:''}${concern?` <strong class="${r.leaving?'red':'gold'}">${esc(concern)}</strong>`:''}${r.repairSince>=0?' A repair is under way: keep the next plan.':''}</p><div class="eyebrow" style="margin-top:8px">RECENTLY</div><ul class="plain">${r.history.slice(-5).reverse().map(x=>`<li>Day ${x.day}: ${esc(x.text)}</li>`).join('')||'<li>Nothing yet.</li>'}</ul></section></div>
 <div class="section-title"><h3>${p.kind==='child'&&p.stage!=='adult'?'PARENTING':'DO SOMETHING TOGETHER'}</h3><span>${free?'AVAILABLE TODAY':'PLAN FOR '+WEEKDAYS[nextFreeDay(p,H().day+1)%7].toUpperCase()}</span></div><div class="actions profile-actions">${actions}</div></div>`;}
function renderPlanner(){const pp=PP(),h=H(),today=h.day;const days=[...Array(7)].map((_,i)=>today+i);const items=d=>pp.plans.filter(c=>c.day===d);
 const work=`Routine ${automatic()>0?'runs every day':'not yet unlocked'} · rest ${h.fx.restDay===today?'taken':'available'} today`;const loans=h.loans.slice().sort((a,b)=>a.nextDue-b.nextDue).filter(l=>l.nextDue<today+7);
 return `<div class="life-section-intro"><h2>This week.</h2><p>Day ${today} · ${WEEKDAYS[weekday()]} · season ${season()+1}. A day is 60 seconds of play. Plans wait for you; nothing is missed while you\'re away.</p></div><div class="week">${days.map(d=>`<div class="wday ${d===today?'today':''}"><div class="wday-h">${WEEKDAYS[d%7]}<small>day ${d}</small></div>${items(d).map(c=>`<div class="witem ${c.type}"><strong>${esc(c.label)}</strong><small>${esc(person(c.person)?.name.split(' ')[0]||'')} · ${c.type}</small><span class="wact">${button('Move','ppl-move',c.id,null,false,'ghost')}${button('Cancel','ppl-cancel',c.id,null,false,'ghost')}</span></div>`).join('')}${loans.filter(l=>l.nextDue===d).map(l=>`<div class="witem duty"><strong>${esc(l.name)}</strong><small>${money(loanDue(l))} due</small></div>`).join('')}${d===today?`<div class="witem note"><small>${work}</small></div>`:''}</div>`).join('')}</div>
 <div class="lhc-grid"><section class="panel"><div class="eyebrow">ROUTINES</div>${pp.routines.length?pp.routines.map((r,i)=>`<div class="line"><span>${esc(ACTIVITIES[r.activity].name)} with ${esc(person(r.person)?.name)} · ${WEEKDAYS[r.weekday]}s</span>${button('End','ppl-routine-end',String(i),null,false,'ghost')}</div>`).join(''):'<p class="small muted">No routines. Add one from a person\'s Plan menu — a weekly dinner keeps a relationship steady without constant attention.</p>'}</section><section class="panel"><div class="eyebrow">HOW COMMITMENTS WORK</div><p class="small"><strong>Plan:</strong> optional; skipping costs almost nothing. <strong>Promise:</strong> you said you would; breaking it costs trust. <strong>Responsibility:</strong> a child\'s event or a partner\'s milestone; missing it costs more. Reschedule once freely. At most 10 open commitments.</p></section></div>`;}
function renderMemories(){const pp=PP(),mem=pp.memories.slice().reverse();return `<div class="life-section-intro"><h2>Your memory book.</h2><p>${mem.length?mem.length+' moments, kept.':'Empty for now. Meet someone, make a promise, come home.'} Memories stay even when people move on.</p></div><div class="memories">${mem.map(m=>`<article class="memory"><div class="memory-people">${m.people.map(id=>person(id)?portraitSVG(person(id),{cls:'tiny'}):'').join('')}</div><div><span class="eyebrow">SEASON ${m.season+1} · ${esc((HOMES.find(x=>x.id===m.home)||HOMES[0]).name).toUpperCase()}${m.gen!==S.generation?' · GENERATION '+m.gen:''}</span><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p></div></article>`).join('')||''}</div>${pp.archive.length?`<div class="section-title"><h3>PAST GENERATIONS</h3></div>${pp.archive.map(a=>`<section class="panel"><div class="eyebrow">GENERATION ${a.generation}</div><p>${esc(a.summary)}</p><ul class="plain">${a.memories.slice(-8).map(m=>`<li>${esc(m.title)}</li>`).join('')}</ul></section>`).join('')}`:''}`;}
function renderTree(){const pp=PP(),met=metPeople();if(!met.length)return '';const you=`<div class="tree-node you"><strong>You</strong><small>${pp.status==='married'?'married':pp.status==='together'?'living with a partner':pp.status==='dating'?'dating':pp.status==='separated'?'separated':'single'}</small></div>`;
 const edge=(p,how)=>`<div class="tree-node"><span>${portraitSVG(p,{cls:'tiny'})}</span><strong>${esc(p.name.split(' ')[0])}</strong><small>${esc(how)}</small></div>`;
 const partner=pp.partner?[edge(person(pp.partner),TIER_LABEL[tierOf(person(pp.partner))].toLowerCase())]:[];const exes=pp.exes.map(id=>person(id)).filter(Boolean).map(p=>edge(p,'former partner'));
 const kids=allKids().map(k=>edge(k,(k.adopted?'adopted, ':'')+(k.home?'at home':'moved out')+(k.parents.filter(x=>x!=='you').map(id=>person(id)?', with '+person(id).name.split(' ')[0]:'').join(''))));
 const friends=met.filter(p=>p.kind==='adult'&&!p.home&&!pp.exes.includes(p.id)&&['friend','close'].includes(tierOf(p))).map(p=>edge(p,tierOf(p)==='close'?'chosen family':'friend'));
 return `<div class="section-title"><h3>RELATIONSHIP MAP</h3></div><div class="tree">${you}${partner.length||exes.length?`<div class="tree-row"><small>PARTNERS</small>${partner.join('')}${exes.join('')}</div>`:''}${kids.length?`<div class="tree-row"><small>CHILDREN</small>${kids.join('')}</div>`:''}${friends.length?`<div class="tree-row"><small>FRIENDS & CHOSEN FAMILY</small>${friends.join('')}</div>`:''}</div>`;}
function planModal(id){const p=person(id);if(!p)return;const h=H();const opts=Object.entries(ACTIVITIES).filter(([k])=>!['apologize','listen','gift'].includes(k)&&!(k==='celebrate'&&!p.milestone));const d=nextFreeDay(p,h.day+1);const conflict=planConflict(d);
 openModal('Plan with '+p.name,`<p>${esc(p.name.split(' ')[0])} is free ${p.kind==='child'||p.home?'any day':p.avail.map(x=>WEEKDAYS[x]).join(', ')}. Next: <strong>${WEEKDAYS[d%7]}, day ${d}</strong>.${conflict?` <span class="red">You already have ${esc(conflict.label)} that day; this will replace it.</span>`:''}</p><div class="event-options">${opts.map(([k,a])=>`<button class="btn" data-action="ppl-plan-set" data-id="${p.id}:${k}:plan:${d}"><span>${a.name}</span><small>${esc(a.desc)}</small></button>`).join('')}<button class="btn primary" data-action="ppl-plan-set" data-id="${p.id}:coffee:promise:${d}"><span>Promise an evening</span><small>Counts more when kept, costs more when broken.</small></button><button class="btn ghost" data-action="ppl-plan-set" data-id="${p.id}:coffee:routine:${d%7}"><span>Weekly routine · ${WEEKDAYS[d%7]}s</span><small>A standing plan that renews itself.</small></button><button class="btn ghost" data-action="close">Not now</button></div>`);}
function adoptFlow(){const pp=PP(),home=activeHome();if(home.rooms<2){note('Adoption needs a home with at least two rooms.');return false;}if(runwayDays()<10||H().arrears>0){note('Agencies ask for stable finances first: positive cash flow and no overdue bills.');return false;}if(kidsAtHome().length>=3){note('Three kids at home is the limit for now.');return false;}addChild(true);return true;}
function peopleAttention(x){const pp=PP();for(const p of metPeople()){if(p.rel.leaving)x.push(['bad',`${p.name} is thinking about leaving`,'life','people']);else if(p.home&&p.rel.tension>=60)x.push(['warn',`Tension with ${p.name.split(' ')[0]}`,'life','people']);}const today=pp.plans.filter(c=>c.day===H().day);if(today.length)x.push(['warn',`${today.length} plan${today.length>1?'s':''} today`,'life','planner']);for(const k of kidsAtHome())if(k.wellbeing<40)x.push(['warn',`${k.name} isn\'t doing well`,'life','people']);}
function peopleRecommend(x){const pp=PP();for(const p of metPeople())if(p.home&&p.rel.repairSince>=0){x.push(`Keep your next plan with ${p.name.split(' ')[0]} — that\'s what closes the apology.`);break;}for(const p of metPeople())if(p.milestone&&['friend','close','dating','partner','spouse'].includes(tierOf(p))){x.push(`${p.name.split(' ')[0]} has something to celebrate. Be there.`);break;}if(pp.household.length&&!Object.keys(pp.flags).some(k=>k.startsWith('act:')&&pp.flags[k]===H().day))x.push('Do one thing at home together today: a meal, a film, a garden hour.');}
function archivePeople(prev){const pp=prev.people;if(!pp)return [];const names=metPeople(prev).map(p=>`${p.name} (${TIER_LABEL[tierOf(p)]})`);const summary=`Generation ${prev.generation}: ${pp.status==='married'?'married to '+person(pp.partner,prev)?.name:pp.status==='together'?'lived with '+person(pp.partner,prev)?.name:'single'}${allKids(prev).length?', '+allKids(prev).length+' child'+(allKids(prev).length>1?'ren':'')+': '+allKids(prev).map(k=>k.name).join(', '):''}. ${names.length} people known.`;return [...pp.archive,{generation:prev.generation,summary,memories:pp.memories.map(m=>({title:m.title,text:m.text,season:m.season})),people:names}].slice(-10);}

function lifeNav(l){const groups=[['HOUSEHOLD',[['overview','Overview'],['home','At home'],['people','People'],['planner','Planner'],['memories','Memories']]],['MONEY & PROPERTY',[['budget','Budget & debt'],['upkeep','Upkeep'],['properties','Properties'],['decorate','Decorate'],['garage','Garage'],['activities','Hobbies & extras']]]];return '<nav class="life-nav" aria-label="Life sections">'+groups.map(([g,items])=>'<div class="life-group"><small>'+g+'</small><div class="life-tabs">'+items.map(([id,title])=>'<button data-action="life-view" data-id="'+id+'" aria-pressed="'+(l.view===id)+'">'+title+'</button>').join('')+'</div></div>').join('')+'</nav>';}
Object.assign(EVENTS,P_EVENTS);Object.assign(EVENT_PRIORITY,P_PRIORITY);

